"""Fiktive, nicht voraufgelöste Grundbuchakten für den gemeinsamen Renderer."""
def doc(file,title,date,body,**kwargs):
    return dict(file=file,title=title,date=date,body=body,**kwargs)
def mail(file,title,date,body,sender,recipient):
    return doc(file,title,date,body,**{'from':sender,'to':recipient,'subject':title})
CASES=[{
'slug':'grundbuchamt-kopiererbrief','plugin':'grundbuchamt-assistent','title':'Der Brief hinter dem Kopierer','subtitle':'Traudel Zwirn, ein Ersatzbrief und eine Anschlussfinanzierung','date':'01.10.2026','client':'Traudel Zwirn',
'summary':'Traudel Zwirn betreibt eine kleine Textilwerkstatt in Hildesheim. Nach monatelanger Suche, einem Aufgebotsverfahren und der Ausgabe eines Ersatzbriefs wird beim Austausch des Bürokopierers ein alter Umschlag gefunden. Die Bank erwartet wenige Tage später die Unterlagen für eine Anschlussfinanzierung.',
'assignment':'Lesen Sie die Unterlagen und erstellen Sie die jetzt benötigten Schreiben an die beteiligten Stellen. Klären Sie die Identität und Verwahrung beider Briefe, den Verfahrensstand und die Auswirkungen auf den laufenden Finanzierungsvorgang. Fragen Sie nur nach Angaben, die in der Akte nicht beantwortet sind.',
'documents':[
doc('01_mandat_zwirn.docx','Mandatsauftrag Traudel Zwirn','01.10.2026','Sehr geehrte Frau Rechtsanwältin Quast,\n\nbitte bringen Sie Ordnung in die Sache mit meinem Haus und dem Grundschuldbrief. Die alte Finanzierung ist längst bezahlt; ich will die Grundschuld aber für die neue Hallenheizung verwenden. Frau Eder von der Bank hat den neuen Brief im September bekommen. Gestern kam beim Abbau des Kopierers ein Umschlag zum Vorschein. Meine Mitarbeiterin meint, das sei genau der gesuchte alte Brief.\n\nIch möchte keine zweite Sicherheit bestellen, wenn das gar nicht nötig ist. Vor allem möchte ich nichts falsch wegwerfen. Bitte bereiten Sie alle erforderlichen Schreiben vor und sagen Sie mir, wem ich welches Original geben soll. Ich möchte die Briefe vor dem Versand sehen. Eine Löschung habe ich nicht beauftragt. Den alten Umschlag habe ich in einen neuen A4-Umschlag gelegt und in den Büroschrank eingeschlossen.\n\nMit freundlichen Grüßen\nTraudel Zwirn',sender='Traudel Zwirn',recipient='Rechtsanwältin Dr. Elsbeth Quast',reference='Q 184/26'),
doc('02_grundbuch_auszug_arbeitskopie.pdf','Grundbuch von Hildesheim, Blatt 28461 – Arbeitsabschrift','20.09.2026','Amtsgericht Hildesheim. Grundbuch von Hildesheim, Blatt 28461. Übertragung des zur Akte gereichten Auszugs; ohne Beglaubigungsvermerk.\n\nBestandsverzeichnis: laufende Nummer 1, Gemarkung Hildesheim, Flur 16, Flurstück 208/7, Gebäude- und Freifläche, Weberschuppen 14, Größe 684 m².\n\nAbteilung 1: laufende Nummer 2, Traudel Zwirn, geboren am 14.03.1962, eingetragen am 18.08.1998 aufgrund Auflassung vom 04.06.1998.\n\nAbteilung 2: keine Eintragungen.\n\nAbteilung 3: laufende Nummer 1, 120.000,00 EUR Grundschuld für die Leine-Kreditbank eG, Hildesheim, nebst 15 % Jahreszinsen und einmaliger Nebenleistung von 5 %. Vollstreckbar nach § 800 ZPO. Gemäß Bewilligung vom 17.04.2008 eingetragen am 12.05.2008. Brief erteilt. Keine nachfolgenden Belastungen.\n\nVermerk zur Aktenabschrift: Der Abruf wurde durch Notar Fridolin Hopf im beauftragten Finanzierungsvorgang vorgenommen. Die Originaldatei liegt im Notariat.'),
doc('03_bestellungsurkunde_abschrift.pdf','Grundschuldbestellung – Textabschrift aus Urkunde 217/2008','17.04.2008','Notar Dr. Fridolin Hopf, Hildesheim. Urkundenrolle 217/2008. Arbeitsabschrift der für den Finanzierungsvorgang maßgeblichen Regelungen.\n\nTraudel Zwirn bestellt an dem Grundbesitz im Grundbuch von Hildesheim Blatt 28461 eine Grundschuld zugunsten der Leine-Kreditbank eG über 120.000,00 EUR. Das Recht erhält 15 Prozent jährliche Zinsen und eine einmalige Nebenleistung von 5 Prozent des Grundschuldbetrags. Die Erteilung eines Briefs wird nicht ausgeschlossen.\n\nDie Eigentümerin bewilligt und beantragt die Eintragung. Sie unterwirft den bezeichneten Grundbesitz wegen des Grundschuldbetrags, der Zinsen und der Nebenleistung der sofortigen Zwangsvollstreckung in der Weise, dass diese gegen den jeweiligen Eigentümer zulässig sein soll.\n\nDer Brief soll nach Eintragung an die Leine-Kreditbank eG, Abteilung Sicherheiten, versandt werden. Die Sicherungsvereinbarung mit der Bank ist gesondert geschlossen. Diese Arbeitsabschrift enthält weder Unterschrift noch Siegel und ist keine Ausfertigung.'),
doc('04_bank_rueckgabe_2019.docx','Rückgabe von Sicherheitenunterlagen','06.06.2019','Sehr geehrte Frau Zwirn,\n\ndas Darlehen 7100842 ist nach unserer Abrechnung zum 31.05.2019 vollständig zurückgeführt. Wie von Ihnen gewünscht, übersenden wir den Grundschuldbrief Gruppe 02 Nummer 864219 über 120.000,00 EUR zum Grundbuch von Hildesheim Blatt 28461. Eine Löschung der Grundschuld haben Sie derzeit nicht gewünscht.\n\nMit der Rücksendung erklären wir keine Abtretung des dinglichen Rechts. Soweit Sie die Grundschuld für eine spätere Finanzierung verwenden möchten, bitten wir um erneute Abstimmung. Die geschlossene Sicherungsvereinbarung und die Rückgewährabwicklung bleiben von der bloßen Übersendung des Briefs zu unterscheiden.\n\nDie Sendung enthält den Grundschuldbrief im Original und dieses Begleitschreiben. Bitte bewahren Sie den Brief sorgfältig auf; für eine spätere Verfügung wird das Original benötigt.\n\nMit freundlichen Grüßen\nBrunhilde Eder\nLeine-Kreditbank eG',sender='Leine-Kreditbank eG',recipient='Traudel Zwirn'),
doc('05_bueroeingang_2019.txt','Büroeingangsbuch – übertragener Eintrag','11.06.2019','11.06.2019, 10:25 Uhr. B. Mückenschreck nimmt einen festen Umschlag der Leine-Kreditbank für Frau Zwirn an. Außen steht „Sicherheitenunterlagen“. Umschlag auf den kleinen Tisch neben dem Kopierer gelegt, weil Frau Zwirn im Kundentermin ist.\n\n12.06.2019, 08:40 Uhr. Traudel: „Die Banksachen mache ich nachher. Bitte nicht unter die Rechnungen.“\n\nWeitere Eintragung auf dieser Seite: Tonerbestellung und Abholung von zwei Musterrollen. Ein gesonderter Vermerk über das Öffnen oder die Weitergabe des Bankumschlags ist im Eingangsbuch nicht vorhanden.\n\nAbgeschrieben am 15.10.2025 durch Balthasar Mückenschreck; Originalbuch befindet sich im Büro der Textilwerkstatt.'),
mail('06_finanzierungsanfrage.eml','Neue Heizung – vorhandene Sicherheit verwenden','2025-09-18T09:12:00+02:00','Guten Morgen Frau Eder,\n\nfür den Austausch der Hallenheizung brauche ich voraussichtlich 82.000 Euro. Ich würde gern die alte Grundschuld verwenden. Ich dachte, der Brief sei noch bei Ihnen. Im Ordner „Haus“ habe ich nur die Kopie von 2008 und Ihr Schreiben aus 2019 gefunden.\n\nBitte prüfen Sie zunächst, welche Unterlagen Sie wirklich brauchen. Ich habe noch keinen Installationsauftrag unterschrieben. Das Angebot läuft bis Ende Oktober.\n\nViele Grüße\nTraudel Zwirn','Traudel Zwirn <traudel@zwirnwerk.example>','Brunhilde Eder <b.eder@leine-kredit.example>'),
mail('07_bank_archivantwort.eml','Originalversand vom Juni 2019','2025-09-22T14:35:00+02:00','Sehr geehrte Frau Zwirn,\n\nunser Archiv enthält das Rückgabeschreiben vom 06.06.2019 und den Postausgangseintrag. Einen Rücklauf der Sendung haben wir nicht gefunden. In unserem Tresorfach liegt der Brief nicht. Eine digitalisierte Briefkopie einschließlich Rückseite senden wir Ihnen separat.\n\nBitte prüfen Sie auch private Unterlagen und die Büroablage. Wir führen die Grundschuld weiterhin auf unseren Namen. Eine Abtretung oder Teilabtretung ist nach unserem Sicherheitenregister nicht erfolgt. Für den neuen Kredit ist noch eine neue Sicherungsvereinbarung nötig.\n\nMit freundlichen Grüßen\nBrunhilde Eder','Brunhilde Eder <b.eder@leine-kredit.example>','Traudel Zwirn <traudel@zwirnwerk.example>'),
doc('08_suchprotokoll.docx','Suchprotokoll Büro und Wohnung','20.10.2025','Traudel Zwirn und Balthasar Mückenschreck haben am 13., 15. und 20.10.2025 die Ablagen „Haus“, „Bank“, „Privat 2019“ und den Bürotresor durchsucht. Im privaten Schreibtisch wurden Versicherungsscheine und der Kaufvertrag von 1998 gefunden. Der Grundschuldbrief lag dort nicht.\n\nDer Kopierer steht seit 2016 in einer Nische und ist mit einem Unterschrank verschraubt. Die sichtbaren Fächer wurden ausgeräumt. Das Gerät wurde nicht von der Wand gezogen; der Techniker hatte uns bei einer früheren Wartung gesagt, dass die Verkabelung dabei beschädigt werden könne.\n\nIm Keller stehen noch drei beschriftete Kartons mit Stoffmustern. Sie wurden geöffnet; ein Bankumschlag war nicht darunter. Frau Zwirn erinnert sich nicht daran, den Umschlag von 2019 geöffnet zu haben. Herr Mückenschreck erinnert sich an die Annahme, nicht an eine spätere Übergabe.\n\nDas Protokoll gibt unseren jeweiligen Kenntnisstand wieder. Eine Vernichtung des Briefs können wir nicht bestätigen.\n\nTraudel Zwirn – Balthasar Mückenschreck'),
doc('09_bank_ermaechtigung.docx','Erklärung zum Aufgebotsverfahren und zur künftigen Verwahrung','03.11.2025','Die Leine-Kreditbank eG bestätigt, dass sie Inhaberin der im Grundbuch von Hildesheim Blatt 28461, Abteilung 3 laufende Nummer 1, eingetragenen Briefgrundschuld über 120.000,00 EUR ist. Eine Verfügung über das Recht zugunsten Dritter ist nach Prüfung unserer Register nicht erfolgt.\n\nWir ermächtigen Frau Traudel Zwirn, das Aufgebotsverfahren zur Kraftloserklärung des abhandengekommenen Grundschuldbriefs Gruppe 02 Nummer 864219 im eigenen Namen zu betreiben. Wir unterstützen die Klärung des Verlusts und werden gerichtliche Rückfragen zu unserem früheren Besitz beantworten.\n\nDie Grundschuld soll nach Abschluss des Verfahrens für eine mögliche neue Finanzierung erhalten bleiben. Eine Löschung oder Abtretung wird mit dieser Erklärung nicht bewilligt. Die Erteilung und Aushändigung eines Ersatzbriefs soll gesondert mit uns und dem beauftragten Notariat abgestimmt werden.\n\nBrunhilde Eder und Ottokar Noll\nLeine-Kreditbank eG',sender='Leine-Kreditbank eG',recipient='Traudel Zwirn'),
doc('10_antrag_aufgebot_arbeitskopie.docx','Eingereichter Aufgebotsantrag – Aktenkopie','17.11.2025','An das Amtsgericht Hildesheim – Aufgebotssachen –\n\nTraudel Zwirn beantragt, den Grundschuldbrief Gruppe 02 Nummer 864219 vom 12.05.2008 über die im Grundbuch von Hildesheim Blatt 28461, Abteilung 3 laufende Nummer 1, eingetragene Grundschuld über 120.000,00 EUR für kraftlos zu erklären.\n\nDas Original ist nach der Rücksendung durch die Gläubigerin nicht mehr auffindbar. Der letzte dokumentierte Eingang liegt am 11.06.2019. Die seit September 2025 unternommenen Suchmaßnahmen ergeben sich aus dem beigefügten Protokoll. Eine Kopie des Briefs und die Ermächtigung der Leine-Kreditbank eG vom 03.11.2025 liegen bei. Die Antragstellerin beabsichtigt, das Recht für die Finanzierung der Heizungsanlage ihres Gebäudes weiterzuverwenden.\n\nDie Antragstellerin bietet an, die Wahrheit ihrer tatsächlichen Angaben an Eides statt zu versichern. Die nähere Erklärung über eigene Wahrnehmungen und fremde Mitteilungen ist beigefügt.\n\nFür die Antragstellerin\nNotar Dr. Fridolin Hopf\nAktenkopie ohne Signaturabbildung'),
doc('11_gericht_nachfrage.docx','Nachfrage zu Briefmerkmalen und Suchumfang','01.12.2025','Sehr geehrter Herr Notar,\n\nim Verfahren 12 II 94/25 wird um Ergänzung gebeten. Die vorgelegte Briefkopie lässt die letzte Ziffer der Nummer auf der Vorderseite nicht sicher erkennen. Bitte reichen Sie eine lesbare Wiedergabe oder einen geeigneten Ausstellungsnachweis nach.\n\nFerner wird um Klarstellung gebeten, ob die im Suchprotokoll genannten Räume einschließlich der nicht ohne Weiteres zugänglichen Ablagebereiche überprüft wurden. Die Erklärung soll zwischen eigener Wahrnehmung und Angaben anderer Personen unterscheiden. Eine absolute Gewissheit über den Verlustort wird damit nicht verlangt.\n\nDie Antragstellerin wird gebeten, die angebotene Versicherung in Abstimmung mit der Geschäftsstelle abzugeben. Ein Termin kann nach Eingang der Ergänzung vereinbart werden.\n\nMit freundlichen Grüßen\nGerda Feldhahn\nRechtspflegerin\nTextabschrift des zur Akte gereichten Schreibens',sender='Amtsgericht Hildesheim',recipient='Notar Dr. Fridolin Hopf',reference='12 II 94/25'),
mail('12_ergaenzung_suche.eml','Ergänzung zur Suche – Kopierernische','2025-12-04T16:42:00+01:00','Sehr geehrter Herr Hopf,\n\ndie Nummer endet laut der jetzt von Frau Eder geschickten deutlicheren Kopie auf 219. Ich habe nochmals alles vor und neben dem Kopierer abgesucht. Hinter das schwere Gerät konnte ich nicht schauen. Ich möchte nicht erklären, dass wir dort gesucht hätten. Der Wartungstermin wurde wegen eines Ersatzteils verschoben.\n\nAnsonsten stimmt das Protokoll. Balthasar weiß noch, dass er den Umschlag auf den kleinen Tisch gelegt hat. Ob ich ihn damals mit nach Hause nahm, weiß ich nicht mehr. Bitte übernehmen Sie diese Unsicherheit so.\n\nMit freundlichen Grüßen\nTraudel Zwirn','Traudel Zwirn <traudel@zwirnwerk.example>','Notar Dr. Fridolin Hopf <kanzlei@hopf-notar.example>'),
doc('13_gericht_erklaerung_protokoll.pdf','Erklärung im Aufgebotsverfahren – Textabschrift','12.12.2025','Amtsgericht Hildesheim, 12 II 94/25. Textabschrift des zur Akte gereichten Protokolls.\n\nTraudel Zwirn erklärt nach Belehrung über die Bedeutung einer Versicherung an Eides statt und die strafrechtlichen Folgen einer unrichtigen Erklärung: Die in ihrer Erklärung vom 04.12.2025 beschriebenen eigenen Wahrnehmungen und Unsicherheiten seien zutreffend. Sie habe das Original seit dem dokumentierten Posteingang nicht selbst sicher identifiziert. Die in der Anlage beschriebenen Suchmaßnahmen seien durchgeführt worden; der Bereich unmittelbar hinter dem feststehenden Kopierer sei nicht zugänglich gewesen.\n\nSie habe den Brief nach ihrer Kenntnis weder verpfändet noch zur Abtretung oder anderweitigen Verfügung überlassen. Eine sichere Aussage über den Zeitpunkt oder Ort des Verlusts könne sie nicht treffen.\n\nDie Erklärung wird von der Antragstellerin an Eides statt versichert. Die Textabschrift bildet keine Unterschriften oder Siegel ab. Das gerichtliche Original verbleibt in der Aufgebotsakte.'),
doc('14_aufgebot_arbeitsabschrift.pdf','Aufgebot – Arbeitsabschrift','08.01.2026','Amtsgericht Hildesheim, 12 II 94/25.\n\nAuf Antrag von Traudel Zwirn wird der Inhaber des Grundschuldbriefs Gruppe 02 Nummer 864219 vom 12.05.2008 über 120.000,00 EUR, eingetragen im Grundbuch von Hildesheim Blatt 28461, Abteilung 3 laufende Nummer 1, aufgefordert, seine Rechte unter Vorlegung der Urkunde bis zum 22.05.2026 anzumelden. Andernfalls kann die Kraftloserklärung der Urkunde erfolgen.\n\nDie Urkunde betrifft das Grundstück Gemarkung Hildesheim, Flur 16, Flurstück 208/7. Als Gläubigerin ist die Leine-Kreditbank eG bezeichnet. Die Grundschuld trägt 15 Prozent jährliche Zinsen und eine einmalige Nebenleistung von 5 Prozent.\n\nDiese zur Mandatsakte genommene Textabschrift gibt den Aufgebotsinhalt wieder. Der Veröffentlichungsnachweis wird in der gerichtlichen Akte geführt.'),
doc('15_verfahrensnotiz.txt','Telefonnotiz der Notariatsmitarbeiterin','29.05.2026','29.05.2026, 11:10 Uhr. Hulda Morgenstern telefoniert mit der Geschäftsstelle zum Aktenzeichen 12 II 94/25. Nach Auskunft der Geschäftsstelle ist bis zum Anmeldezeitpunkt keine Urkunde vorgelegt worden. Die Akte liegt zur Entscheidung vor. Ein genauer Entscheidungstermin wurde nicht genannt.\n\nFrau Zwirn wurde um 11:35 Uhr über diesen Stand informiert. Sie fragte, ob sie nun den Heizungsauftrag erteilen könne. Frau Morgenstern sagte, dass das Notariat keine Kreditzusage erteile und die Bankentscheidung gesondert abgewartet werden müsse.\n\nWiedervorlage für eine Sachstandsanfrage am 19.06.2026. Ein Ersatzbrief wurde bislang nicht beantragt; hierzu fehlt noch der Beschluss.'),
doc('16_ausschliessungsbeschluss_abschrift.pdf','Ausschließungsbeschluss – Textabschrift','04.06.2026','Amtsgericht Hildesheim, 12 II 94/25.\n\nDer Grundschuldbrief Gruppe 02 Nummer 864219, ausgefertigt am 12.05.2008, über die im Grundbuch von Hildesheim Blatt 28461, Abteilung 3 laufende Nummer 1, eingetragene Grundschuld von 120.000,00 EUR für die Leine-Kreditbank eG mit 15 Prozent jährlichen Zinsen und einmaliger Nebenleistung von 5 Prozent wird für kraftlos erklärt.\n\nDie Urkunde ist innerhalb des im Aufgebot bestimmten Zeitraums nicht vorgelegt worden. Die Antragstellerin hat den Verlust und die Tatsachen ihrer Berechtigung glaubhaft gemacht.\n\nDie Kosten des Verfahrens trägt die Antragstellerin. Die beigefügte Rechtsbehelfsbelehrung gehört zum zugestellten gerichtlichen Original.\n\nDie vorliegende Arbeitsabschrift enthält keine Abbildung von Unterschriften oder Siegeln und wird mit der gesonderten Zustell- und Rechtskraftmitteilung verwahrt.'),
doc('17_rechtskraftmitteilung.docx','Mitteilung zum Rechtskraftnachweis','20.07.2026','Sehr geehrter Herr Notar Hopf,\n\nzu Ihrem Ersuchen übersenden wir den Rechtskraftnachweis zu dem Ausschließungsbeschluss vom 04.06.2026 im Verfahren 12 II 94/25. Nach dem Verfahrensstand ist der Beschluss seit dem 17.07.2026 rechtskräftig. Die Ausfertigung mit dem Rechtskraftvermerk wird auf dem vereinbarten Weg an Ihr Büro übermittelt.\n\nBitte verwenden Sie bei Rückfragen weiterhin das oben genannte Aktenzeichen. Eine Erteilung des neuen Grundschuldbriefs ist nicht Gegenstand dieser Mitteilung.\n\nMit freundlichen Grüßen\nGeschäftsstelle des Amtsgerichts Hildesheim\nTextabschrift des zur Akte gereichten Begleitschreibens',reference='12 II 94/25'),
doc('18_bank_antrag_neuer_brief.docx','Antrag der Gläubigerin auf Erteilung eines neuen Briefs','29.07.2026','An das Amtsgericht Hildesheim – Grundbuchamt –\n\ndie Leine-Kreditbank eG beantragt die Erteilung eines neuen Grundschuldbriefs für die im Grundbuch von Hildesheim Blatt 28461, Abteilung 3 laufende Nummer 1, eingetragene Grundschuld über 120.000,00 EUR. Der bisherige Brief Gruppe 02 Nummer 864219 ist durch rechtskräftigen Beschluss des Amtsgerichts Hildesheim vom 04.06.2026, 12 II 94/25, für kraftlos erklärt worden. Die Ausfertigung mit Rechtskraftvermerk wird über Notar Dr. Fridolin Hopf vorgelegt.\n\nWir sind weiterhin Inhaberin des Rechts. Eine Abtretung oder Teilabtretung ist nicht erfolgt. Der neue Brief soll an unsere Abteilung Sicherheiten, zu Händen Brunhilde Eder, ausgehändigt werden. Eine Änderung von Betrag, Rang oder Sicherungszweck wird mit diesem Antrag nicht beantragt.\n\nLeine-Kreditbank eG\nAktenkopie der über das Notariat abgewickelten Erklärung'),
doc('19_ersatzbrief_datenblatt.pdf','Ersatzbrief – Datenabschrift','09.09.2026','Neuer Grundschuldbrief Gruppe 04 Nummer 226731. Datenabschrift des im Notariat eingesehenen Dokuments.\n\nAmtsgericht Hildesheim. Grundbuch von Hildesheim, Blatt 28461, Abteilung 3 laufende Nummer 1. Grundschuld von 120.000,00 EUR für Leine-Kreditbank eG, Hildesheim, mit 15 Prozent jährlichen Zinsen und einer einmaligen Nebenleistung von 5 Prozent.\n\nDer Brief tritt an die Stelle des durch Beschluss vom 04.06.2026, Amtsgericht Hildesheim 12 II 94/25, für kraftlos erklärten Grundschuldbriefs Gruppe 02 Nummer 864219.\n\nAusgestellt am 09.09.2026. Briefversand laut Begleitvermerk am 10.09.2026 an die Leine-Kreditbank eG.\n\nDiese Datenabschrift ist kein Grundschuldbrief. Sie enthält weder Formblattgestaltung noch amtliche Signaturen oder Siegel.'),
mail('20_empfang_bank.eml','Ersatzbrief eingegangen','2026-09-14T10:06:00+02:00','Sehr geehrter Herr Hopf, sehr geehrte Frau Zwirn,\n\nwir bestätigen den Eingang des Ersatzbriefs Gruppe 04 Nummer 226731 am 11.09.2026. Er wurde unter Sicherheiten-ID SI-0842-26 im Tresorbestand erfasst. Der neue Kredit ist noch nicht valutiert; die neue Sicherungsvereinbarung muss abschließend unterzeichnet werden.\n\nBitte senden Sie uns keine weiteren Originale ohne vorherige Abstimmung. Für den Finanzierungstermin am 07.10.2026 benötigen wir außerdem das endgültige Angebot des Heizungsbauers.\n\nMit freundlichen Grüßen\nBrunhilde Eder','Brunhilde Eder <b.eder@leine-kredit.example>','Traudel Zwirn <traudel@zwirnwerk.example>'),
doc('21_kopierer_servicebericht.docx','Servicebericht Austausch Kopierer','30.09.2026','Auftrag K-260930-17, Zwirnwerk, Weberschuppen 14, Hildesheim. Techniker: Juri Kugelblitz. Beginn 08:15 Uhr, Ende 10:05 Uhr.\n\nDas Altgerät wurde vom Unterschrank gelöst und nach vorne gezogen. Hinter der rechten Seitenwand lagen zwei Stoffproben, ein Kugelschreiber und ein verschlossener C4-Umschlag mit dem Absender Leine-Kreditbank eG. Der Umschlag war stark verstaubt, aber trocken. Er lag zwischen Rückwand und Kabelkanal.\n\nIch habe den Umschlag ungeöffnet Frau Zwirn übergeben. Frau Zwirn öffnete ihn in Anwesenheit von Herrn Mückenschreck. Auf einem darin liegenden gefalteten Papier stand nach meiner Wahrnehmung „Grundschuldbrief“. Ich habe den Inhalt nicht weiter geprüft und keine Kopie mitgenommen.\n\nDas Altgerät wurde abgeholt. Die neue Netzwerkverbindung wurde getestet. Frau Zwirn bestätigte den Empfang des Geräts und des gefundenen Umschlags.\n\nJuri Kugelblitz, Kopierknopf Service GmbH'),
doc('22_buerochat_fund.txt','Bürochat nach dem Kopierertausch','30.09.2026','09:48 Balthasar: Traudel, das ist offenbar das alte Papier. Nummer 864219 steht oben. Nicht in den Schredder legen!\n09:50 Traudel: Ich habe es in einen frischen Umschlag getan. Die Bank hat doch schon einen neuen. Muss ich den alten einfach zurückschicken?\n09:53 Balthasar: Bitte erst Hopf fragen. Auf der Rückseite ist nichts Neues, soweit ich sehe.\n10:02 Traudel: Frau Eder ist bis morgen weg. Ich habe nur ihrer Vertretung eine Nachricht aufgesprochen.\n10:07 Balthasar: Und nicht beide Nummern in die Heizungsmappe schreiben. Sonst nehmen die nachher das falsche Papier.\n10:11 Traudel: Ich rufe Quast an. Das Ding bleibt im Schrank.\n\nExport erstellt durch Traudel Zwirn am 01.10.2026. Teilnehmer: Traudel Zwirn und Balthasar Mückenschreck.'),
doc('23_fundaufnahme.docx','Aufnahme des gefundenen Papiers','30.09.2026','Aufgenommen durch Traudel Zwirn und Balthasar Mückenschreck um 10:20 Uhr.\n\nDas Papier trägt die Bezeichnung Grundschuldbrief Gruppe 02 Nummer 864219 und das Datum 12.05.2008. Genannt werden Grundbuch Hildesheim Blatt 28461, 120.000,00 EUR und Leine-Kreditbank eG. Auf der Rückseite sind nach unserer Sichtprüfung keine späteren Abtretungs- oder Teilungsvermerke vorhanden. Die Faltstellen sind gelblich; die Schrift ist lesbar.\n\nIm Umschlag lag zusätzlich das Begleitschreiben vom 06.06.2019. Der Umschlag wurde am Fundtag geöffnet. Seit dem Öffnen wurde das Papier nicht an Dritte ausgehändigt. Es wurde mit dem Büroscanner beidseitig kopiert und danach in einem beschrifteten Umschlag im abgeschlossenen Büroschrank verwahrt.\n\nWir haben weder einen Stempel angebracht noch das Papier gelocht. Die weitere Übergabe soll nach schriftlicher Abstimmung erfolgen.\n\nTraudel Zwirn – Balthasar Mückenschreck'),
doc('24_kosten_und_briefwege.xlsx','Kosten und Briefwege','01.10.2026','',sheets=[{'name':'Auslagen','headers':['Datum','Position','Betrag EUR','Status'],'rows':[['20.11.2025','Gerichtlicher Vorschuss laut Rechnung',180,'bezahlt'],['12.12.2025','Fahrt und Porto laut Büroaufwand',18.4,'bezahlt'],['29.07.2026','Notariat Teilrechnung laut Beleg',214.2,'bezahlt'],['10.09.2026','Versand Ersatzbrief laut Notariat',9.8,'bezahlt'],['01.10.2026','Summe dokumentierte Ausgaben','=SUM(C2:C5)','ohne neue Beratung']], 'formats':{'C':'0.00'}},{'name':'Briefe','headers':['Nummer','Datum','Letzter bestätigter Ort','Beleg'],'rows':[['02/864219','12.05.2008','Büroschrank Zwirnwerk seit 30.09.2026','Fundaufnahme'],['04/226731','09.09.2026','Leine-Kreditbank seit 11.09.2026','Empfangsmail 14.09.2026']]}]),
mail('25_bankvertretung_rueckfrage.eml','Ihr Anruf zum alten Brief','2026-10-01T08:33:00+02:00','Sehr geehrte Frau Zwirn,\n\nFrau Eder hat mich gebeten, Ihren Anruf aufzunehmen. Sie sagten, es sei ein alter Grundschuldbrief gefunden worden. Bitte schicken Sie das Papier heute noch nicht auf dem Postweg. Unser Sicherheitenregister führt bereits den Ersatzbrief 226731. Ich möchte vor einer neuen Originalannahme wissen, zu welchem gerichtlichen Vorgang das gefundene Papier gehört.\n\nBitte lassen Sie uns über Ihre Beraterin eine Kopie beider Seiten sowie die Beschlussdaten zukommen. Der Finanzierungstermin bleibt zunächst bestehen. Ob sich daraus weiterer Klärungsbedarf ergibt, prüft Frau Eder nach Eingang.\n\nMit freundlichen Grüßen\nOttokar Noll','Ottokar Noll <o.noll@leine-kredit.example>','Traudel Zwirn <traudel@zwirnwerk.example>')]
}]
CASES.append({
'slug':'grundbuchamt-erben-im-hinterhaus','plugin':'grundbuchamt-assistent','title':'Die Erben im Hinterhaus','subtitle':'Ein öffentliches Testament, drei Geschwister und eine alte Vollmacht','date':'01.10.2026','client':'Nela Lieselotte Bregenzer',
'summary':'Berta Bregenzer hinterlässt ein Berliner Mietshaus und ein notarielles Testament, das ihre Kinder ohne Namen bezeichnet. Drei Geschwister möchten das Grundbuch berichtigen. Während Urkunden zusammengesucht werden, tauchen eine alte Karte aus Prag und eine Vollmacht aus dem Jahr 2011 auf.',
'assignment':'Bearbeiten Sie die Zwischenverfügung anhand der vorhandenen Unterlagen. Formulieren Sie die erforderliche Antwort und die gezielten Nachforderungen. Trennen Sie die Berichtigung nach Erbfolge von der zusätzlich diskutierten Finanzierung; machen Sie aus Familienerinnerungen keine gesicherten Personenstandstatsachen.',
'documents':[
doc('01_auftrag_nela.docx','Auftrag zur Berichtigung des Grundbuchs','01.10.2026','Sehr geehrter Herr Rechtsanwalt Flügel,\n\nmeine Brüder und ich möchten nach dem Tod unserer Mutter das Grundbuch für das Hinterhaus berichtigen lassen. Wir wollen das Haus vorerst gemeinsam behalten. Ich habe den Antrag selbst gestellt, weil im Nachlassgericht gesagt wurde, das notarielle Testament könne reichen. Jetzt verlangt das Grundbuchamt einen Erbschein.\n\nBitte prüfen Sie die beigefügten Unterlagen und schreiben Sie die Antwort. Die Geschichte mit Karim aus Prag möchte ich nicht unter den Tisch fallen lassen, aber auch nicht zu einem neuen Familienkrieg machen. Ich weiß nicht, ob unsere Mutter ihn adoptiert hat. Otto sagt nein, hat dafür aber nur seine Erinnerung.\n\nDie Bank hat außerdem wegen der Dachreparatur nach einer Grundschuld gefragt. Meine Vollmacht von 2011 liegt bei. Bitte prüfen Sie das getrennt; ich habe noch nichts unterschrieben und niemanden zur Belastung bevollmächtigt.\n\nMit freundlichen Grüßen\nNela Lieselotte Bregenzer',reference='F 267/26'),
doc('02_stammdaten.docx','Personen und Kontaktwege','25.09.2026','Berta Bregenzer, geborene Tannhäusel, geboren am 22.02.1940 in Ulm, verstorben am 08.03.2026 in Berlin. Letzte Anschrift: Hinterhofstraße 28, 10439 Berlin.\n\nNela Lieselotte Bregenzer, geboren am 14.07.1968 in Berlin, wohnt in Berlin. Beruf: Restauratorin. Kontakt: nela@hinterhaus.example.\n\nOtto Samir Bregenzer, geboren am 06.11.1971 in Berlin, wohnt in Leipzig. Beruf: Veranstaltungstechniker. Kontakt: otto@hinterhaus.example.\n\nLevin Gottlieb Bregenzer, geboren am 28.01.1978 in Berlin, wohnt in Tübingen. Beruf: Bibliothekar. Kontakt: levin@hinterhaus.example.\n\nKarim Vlk, nach der beigefügten Karte wohnhaft in Prag. Geburtsdatum und heutige Anschrift liegen Nela nicht vor. Berta bezeichnete ihn bei Familienfeiern gelegentlich als ihren Prager Jungen. Aus der Kontaktliste allein ergibt sich keine Aussage über Abstammung oder Adoption.\n\nZusammengestellt von Nela Bregenzer für die Mandatsaufnahme.'),
doc('03_grundbuch_pankow.pdf','Grundbuch Prenzlauer Berg Blatt 39127 – Arbeitsabschrift','16.09.2026','Amtsgericht Pankow, Grundbuch von Prenzlauer Berg, Blatt 39127. Arbeitsabschrift des vollständigen zur Akte gereichten Auszugs.\n\nBestandsverzeichnis: Gemarkung Prenzlauer Berg, Flur 112, Flurstück 76/4, Wohn- und Geschäftshaus, Hinterhofstraße 28, 524 m².\n\nAbteilung 1: Berta Bregenzer, geboren am 22.02.1940. Eingetragen seit 11.09.1997.\n\nAbteilung 2: laufende Nummer 1, beschränkte persönliche Dienstbarkeit für die Berliner Wasserbogen GmbH zur Führung und Unterhaltung einer Wasserleitung. Gemäß Bewilligung vom 04.06.1996.\n\nAbteilung 3: laufende Nummer 2, 95.000,00 EUR Grundschuld ohne Brief für die Stadtfenster Bank AG mit 12 Prozent Jahreszinsen und 5 Prozent Nebenleistung. Eingetragen am 18.10.2011.\n\nKeine Löschung des Rechts in Abteilung 3 und keine Eintragung der Erben im vorliegenden Auszug.'),
doc('04_testament_oeffentliche_abschrift.pdf','Notarielles Testament – Arbeitsabschrift','14.05.2007','Notarin Hildegard Funkenstein, Berlin. Urkundenrolle 284/2007. Arbeitsabschrift des in der Nachlassakte eröffneten Testaments.\n\nBerta Bregenzer erklärt: Ich widerrufe meine bisherigen Verfügungen von Todes wegen. Zu meinen Erben setze ich meine Kinder zu gleichen Teilen ein. Sollte eines meiner Kinder vor mir versterben, treten seine Abkömmlinge nach den Regeln der gesetzlichen Erbfolge an seine Stelle.\n\nMein Haus in der Hinterhofstraße soll möglichst in der Familie bleiben. Dieser Wunsch ist keine Anordnung einer dauerhaften Bindung und kein Verbot einer späteren einvernehmlichen Veräußerung. Eine Testamentsvollstreckung ordne ich nicht an.\n\nMeine Tochter Nela soll bei der Verwaltung praktisch die erste Ansprechpartnerin sein. Ihr steht aus dieser Bitte kein zusätzlicher Erbteil zu. Im Übrigen sollen meine Erben gemeinsam entscheiden.\n\nDie Urkunde wurde in der im gerichtlichen Original dokumentierten Form errichtet. Diese Arbeitsabschrift enthält keine nachgebildeten Signaturen oder Siegel.'),
doc('05_eroeffnung_niederschrift.pdf','Eröffnungsniederschrift – Textabschrift','14.04.2026','Amtsgericht Pankow, Nachlassgericht, 62 IV 381/26. Textabschrift der zur Akte gereichten Niederschrift.\n\nDie öffentliche Verfügung von Todes wegen der am 08.03.2026 verstorbenen Berta Bregenzer vom 14.05.2007, Urkundenrolle 284/2007 der Notarin Hildegard Funkenstein, wurde am 14.04.2026 eröffnet. Die anwesende Geschäftsstelle hat die Urkunde der Nachlassakte zugeordnet. Weitere Verfügungen befanden sich an diesem Tag nicht in der Akte.\n\nBenachrichtigt wurden Nela Lieselotte Bregenzer, Otto Samir Bregenzer und Levin Gottlieb Bregenzer. Aus dem Benachrichtigungsvermerk folgt keine abschließende Feststellung der Erbenstellung.\n\nEine beglaubigte Abschrift der Verfügung und der Eröffnungsniederschrift wurde Nela Bregenzer am 21.04.2026 erteilt. Diese Textabschrift bildet die amtlichen Beglaubigungen nicht ab.'),
doc('06_personenstand_bestaetigung.docx','Begleitschreiben zu den Personenstandsurkunden','28.04.2026','Sehr geehrte Frau Bregenzer,\n\nauf Ihren Antrag übersenden wir Ihnen die bestellten beglaubigten Abschriften aus den Geburtenregistern für Nela Lieselotte, Otto Samir und Levin Gottlieb Bregenzer. In allen drei Einträgen ist Berta Bregenzer, geborene Tannhäusel, als Mutter bezeichnet. Die in Ihrem Antrag angegebenen Geburtsdaten stimmen mit den Einträgen überein.\n\nDie Ausfertigungen beziehen sich auf die jeweils bezeichnete Person. Sie enthalten keine allgemeine Bescheinigung darüber, ob Berta Bregenzer weitere Kinder hatte oder ob in einem anderen Register ein Adoptionsvorgang beurkundet wurde. Bitte beachten Sie den jeweiligen Inhalt der beigefügten Registerabschrift.\n\nMit freundlichen Grüßen\nStandesamt Berlin-Nordbogen\nTextabschrift des Begleitschreibens; die drei Registerabschriften liegen im Originalumschlag der Mandantin.',sender='Standesamt Berlin-Nordbogen',recipient='Nela Bregenzer'),
doc('07_sterbeurkunde_datenabschrift.pdf','Sterbefall Berta Bregenzer – Datenabschrift','17.03.2026','Sterberegister S 482/2026, Standesamt Berlin-Nordbogen. Datenabschrift der von Nela Bregenzer vorgelegten Urkunde.\n\nBerta Bregenzer, geborene Tannhäusel, geboren am 22.02.1940 in Ulm, ist am 08.03.2026 um 06:45 Uhr in Berlin verstorben. Familienstand: verwitwet. Letzte Anschrift: Hinterhofstraße 28, 10439 Berlin.\n\nAls verstorbener Ehegatte ist Hugo Bregenzer bezeichnet. Das Register weist die für die Sterbefallbeurkundung erhobenen Daten aus. Es enthält keine Feststellung sämtlicher Abkömmlinge oder der Erbfolge.\n\nDie Mandantin hält die erteilte Urkunde in ihrem Dokumentenumschlag bereit. Diese Übertragung dient der Aktenarbeit und ist keine amtliche Ersatzurkunde.'),
doc('08_berichtigungsantrag_nela.docx','Antrag von Nela Bregenzer','02.09.2026','An das Amtsgericht Pankow – Grundbuchamt –\n\nich beantrage, das Grundbuch von Prenzlauer Berg Blatt 39127 nach dem Tod meiner Mutter Berta Bregenzer zu berichtigen. Als Eigentümer sollen Nela Lieselotte Bregenzer, Otto Samir Bregenzer und Levin Gottlieb Bregenzer in Erbengemeinschaft eingetragen werden.\n\nMeine Mutter ist am 08.03.2026 verstorben. Sie hat uns in ihrem notariellen Testament vom 14.05.2007 als ihre Kinder zu gleichen Teilen eingesetzt. Die Verfügung und die Eröffnungsniederschrift sind in beglaubigter Abschrift beigefügt. Außerdem lege ich die Abschriften unserer drei Geburtsregistereinträge und die Sterbeurkunde vor.\n\nWir haben uns bisher nicht auseinandergesetzt. Das Haus soll zunächst gemeinschaftlich verwaltet werden. Eine Übertragung auf mich allein ist nicht beantragt.\n\nMit freundlichen Grüßen\nNela Lieselotte Bregenzer\nAktenkopie der eingereichten Fassung'),
mail('09_otter_bruderfrage.eml','Grundbuch: Warum nicht jeder ein Drittel?','2026-09-03T21:17:00+02:00','Liebe Nela,\n\nich habe deinen Antrag gelesen. Müsste da nicht stehen, dass jeder von uns ein Drittel bekommt? Ich möchte nicht, dass du wegen der Verwaltung später allein entscheiden kannst. Im Testament steht doch, dass wir gemeinsam entscheiden sollen.\n\nMit der Dachreparatur bin ich einverstanden, aber ich will den Kreditvertrag sehen, bevor jemand eine weitere Sicherheit bestellt. Wir haben noch die alte Grundschuld im Buch. Ist die überhaupt bezahlt? Mutter sagte immer, die Bank bekomme nichts mehr von ihr.\n\nBitte stell nichts um, bevor Levin und ich die Unterlagen gesehen haben.\n\nOtto','Otto Samir Bregenzer <otto@hinterhaus.example>','Nela Bregenzer <nela@hinterhaus.example>'),
doc('10_zwischenverfuegung.docx','Zwischenverfügung des Grundbuchamts – Textabschrift','18.09.2026','Amtsgericht Pankow – Grundbuchamt – Aktenzeichen PB-39127-26.\n\nDer beantragten Berichtigung stehen derzeit folgende Hindernisse entgegen. Die letztwillige Verfügung bezeichnet die Kinder der Erblasserin nicht namentlich. Die vorgelegten Geburtsregisterabschriften belegen die Abstammung der Antragsteller, nicht jedoch das Fehlen weiterer Abkömmlinge. Ein Nachweis der vollständigen Erbfolge ist daher bislang nicht geführt.\n\nEs wird aufgegeben, einen die Erbfolge nach Berta Bregenzer vollständig ausweisenden Erbschein vorzulegen. Für die Behebung wird eine Frist bis zum 30.10.2026 gesetzt.\n\nSoweit die Antragstellerin aus der Verfügung eine besondere Vertretungsmacht für die anderen Beteiligten herleiten möchte, wird um Klarstellung gebeten. Eine Verfügung über den Grundbesitz ist mit dem vorliegenden Antrag nicht Gegenstand des Verfahrens.\n\nGertrud Mohnke, Rechtspflegerin. Textabschrift; Zustellumschlag ist gesondert aufbewahrt.'),
doc('11_zustellvermerk.txt','Eingangsvermerk der Mandantin','22.09.2026','Gelber Umschlag am 22.09.2026 um etwa 13:00 Uhr aus dem Briefkasten genommen. Auf dem Umschlag ist als Zustelltag der 21.09.2026 eingetragen. Nela hat das Schreiben am selben Abend eingescannt.\n\nDer Scan wurde unter „Grundbuch_neu“ abgelegt. Das Original und der Umschlag liegen in der roten Mappe.\n\nNela notiert am Rand: „Nicht bis Halloween liegenlassen. Anwalt fragen, ob Erbschein wirklich nötig. Ich habe nie gesagt, dass ich für beide verfügen will.“\n\nLevin bestätigt per Nachricht am 23.09.2026 den Erhalt der weitergeleiteten Datei; Otto antwortet erst am 25.09.2026.'),
doc('12_geschwisterchat.txt','Chat „Hinterhaus, aber bitte friedlich“','25.09.2026','19:08 Nela: Das Gericht will einen Erbschein. Hat irgendwer noch ein anderes Testament?\n19:11 Levin: Ich habe nur die Abschrift von 2007. Die Kiste aus Mutters Kleiderschrank ist noch bei mir.\n19:14 Otto: Wir sind drei. Was soll das Theater?\n19:16 Nela: In der Kiste war doch auch Karim. Mutter schrieb „mein Sohn in Prag“. Weiß jemand, ob da etwas offiziell war?\n19:20 Otto: Das war der Junge vom Austausch. Keine Adoption. Glaube ich jedenfalls.\n19:23 Levin: Bitte „glaube ich“ nicht als amtliche Wahrheit abgeben. Ich suche die Mappe.\n19:25 Nela: Und die alte Vollmacht? Darf ich wenigstens den Dachkredit unterschreiben?\n19:27 Otto: Ich will darüber erst reden. Bitte keine Grundschuld ohne uns.\n\nExport durch Nela am 26.09.2026.'),
doc('13_postkarte_prag.pdf','Postkarte aus Prag – Textübertragung','12.08.1994','Vorderseite: handschriftlicher Vermerk „Prag, Sommer 94“. Die Bildseite wurde nicht mitgescannt.\n\nLiebe Berta,\n\ndanke für deinen langen Brief. Hier ist es heiß, und im Theater bauen wir bis spät in die Nacht. Du fehlst mir mit deinen Butterbroten und deinen furchtbaren Witzen. Wenn ich im Herbst nach Berlin komme, schlafen wir wieder im Hinterhaus, ja?\n\nIch habe noch einmal nach den alten Papieren gefragt. Im Büro ist alles umgezogen. Frau Havel sagt, sie sucht die Mappe. Ich weiß nicht, ob sie dieselben Unterlagen meint wie du.\n\nDein Prager Sohn Karim\n\nRückseitiger Vermerk Bertas: „Karim – unbedingt aufbewahren. Mit Hugo besprechen.“\n\nTextübertragung durch Levin Bregenzer am 26.09.2026. Das Original liegt in der Nachlasskiste.'),
doc('14_vollmacht_2011_abschrift.pdf','Vollmacht von 2011 – Arbeitsabschrift','04.10.2011','Notar Walther Knopfmacher, Berlin, Urkundenrolle 618/2011. Arbeitsabschrift der Nela erteilten Vollmacht.\n\nBerta Bregenzer bevollmächtigt ihre Tochter Nela Lieselotte Bregenzer, sie in Vermögensangelegenheiten zu vertreten. Die Vollmacht umfasst die Verwaltung, Veräußerung und Belastung von Grundbesitz sowie die Abgabe und Entgegennahme der damit zusammenhängenden Erklärungen. Die Bevollmächtigte ist von den Beschränkungen des § 181 BGB befreit.\n\nDie Vollmacht soll durch den Tod der Vollmachtgeberin nicht erlöschen. Ein Widerruf bleibt möglich. Im Innenverhältnis soll die Bevollmächtigte größere Maßnahmen zuvor mit ihren Brüdern besprechen, soweit dies ohne Gefährdung dringlicher Interessen möglich ist. Die Wirksamkeit nach außen soll von dieser Abstimmung nicht abhängig sein.\n\nDer Bevollmächtigten wird eine Ausfertigung erteilt. Diese Aktenabschrift gibt weder den Ausfertigungsvermerk noch Unterschriften oder Siegel wieder.'),
mail('15_nela_ausfertigung.eml','Vollmacht – das Papier ist bei mir','2026-09-27T10:12:00+02:00','Sehr geehrter Herr Flügel,\n\ndie Vollmacht ist nicht nur ein Handyfoto. Ich habe die Ausfertigung in der roten Mappe, mit dem Ausfertigungsvermerk für mich. Ich kann sie vorbeibringen. Von einem Widerruf meiner Mutter weiß ich nichts.\n\nOtto hat am Telefon gesagt, ich solle „mit der Vollmacht bloß nichts mehr machen“. Ob er das als Widerruf gemeint hat oder nur wegen des Kredits, weiß ich nicht. Levin hat sich dazu nicht geäußert. Ich habe seit dem Tod nur Handwerkertermine organisiert und Mieten auf das bisherige Hauskonto laufen lassen.\n\nBitte fragen Sie mich gezielt, was Sie dazu noch benötigen.\n\nMit freundlichen Grüßen\nNela Bregenzer','Nela Bregenzer <nela@hinterhaus.example>','Rechtsanwalt Winfried Flügel <w.fluegel@fluegel-kanzlei.example>'),
mail('16_otto_vorbehalt.eml','Keine neue Belastung ohne Abstimmung','2026-09-27T18:46:00+02:00','Liebe Nela,\n\nzur Klarstellung nach unserem Telefonat: Ich bin dagegen, dass du allein einen neuen Kredit auf das Haus aufnimmst. Ich möchte, dass wir über Betrag, Laufzeit und Sicherheit gemeinsam entscheiden. Meine Bemerkung bezog sich auf dieses Vorhaben. Ob und wie ich die Vollmacht unserer Mutter widerrufen kann, weiß ich nicht.\n\nDie Grundbuchberichtigung auf uns als Erbengemeinschaft soll weitergehen. Ich möchte dazu keinen Streit mit dem Gericht. Wenn die Nachweise reichen, sollten wir unnötige Kosten vermeiden. Bitte leite diese Mail auch dem Anwalt weiter.\n\nOtto','Otto Samir Bregenzer <otto@hinterhaus.example>','Nela Bregenzer <nela@hinterhaus.example>'),
doc('17_bank_dachfinanzierung.docx','Unterlagenanforderung Dachfinanzierung','24.09.2026','Sehr geehrte Frau Bregenzer,\n\nfür die Prüfung eines Darlehens von 74.000,00 EUR zur Dachinstandsetzung benötigen wir das vollständige Angebot, eine Übersicht der Mieteinnahmen und einen aktuellen Eigentumsnachweis. Die bestehende Grundschuld über 95.000,00 EUR wird weiterhin in unserem Sicherheitenbestand geführt. Ob sie für den neuen Kredit verwendet werden kann, ist noch zu prüfen.\n\nBitte teilen Sie mit, wer Darlehensnehmer werden und wer die Sicherungsvereinbarung unterzeichnen soll. Die von Ihnen angesprochene Vollmacht Ihrer Mutter möchten wir vollständig einsehen. Eine Zustimmung zur Belastung oder zur Auszahlung ist mit dieser Unterlagenanforderung nicht verbunden.\n\nDas Finanzierungsangebot wird erst nach Prüfung erstellt. Ihre telefonische Bitte um einen Termin vor dem Winter haben wir notiert.\n\nMit freundlichen Grüßen\nMara Suse Nguyen\nStadtfenster Bank AG'),
doc('18_dachangebot.pdf','Angebot Dachabdichtung Hinterhaus','17.09.2026','Dach & Dachs Bau GmbH, Angebot DD-26117 an die Verwaltung Hinterhofstraße 28.\n\nGegenstand ist die Erneuerung der schadhaften Abdichtung auf dem hinteren Flachdach, einschließlich Rückbau der oberen Lage, Prüfung des Untergrunds, neuer Abdichtung und Anschlussarbeiten an zwei Lichtkuppeln. Die angebotene Fläche beträgt nach Aufmaß 186 m².\n\nNettosumme: 61.680,67 EUR. Umsatzsteuer 19 Prozent: 11.719,33 EUR. Bruttosumme: 73.400,00 EUR.\n\nDas Angebot gilt bis zum 31.10.2026. Der Ausführungstermin wird nach Auftragseingang und Materialbestellung vereinbart. Verdeckte Schäden am Tragwerk sind nicht Bestandteil dieses Angebots und werden vor Zusatzleistungen angezeigt.\n\nEine Bestellung ist uns bisher nicht zugegangen. Ansprechpartner: Boris Knister. Die bloße Reservierung eines Besichtigungstermins löst keinen Bauauftrag aus.'),
doc('19_verwaltung_hauskonto.xlsx','Hauskonto und geplante Dachkosten','30.09.2026','',sheets=[{'name':'Liquiditaet','headers':['Position','Betrag EUR','Belegstand'],'rows':[['Kontostand 30.09.2026',18240,'Bankauszug vorgelegt'],['Rücklage Heizungswartung',3500,'intern vorgesehen'],['Verfügbare Mittel','=B2-B3','ohne Kredit'],['Dachangebot brutto',73400,'Angebot DD-26117'],['Rechnerischer Restbedarf','=B5-B4','keine Kreditzusage']], 'formats':{'B':'0.00'}},{'name':'Nachweise','headers':['Person','Geburtsurkunde','Erklärung weitere Kinder','Originalort'],'rows':[['Nela','vorhanden','bisher nur E-Mail','rote Mappe'],['Otto','vorhanden','noch nicht abgegeben','bei Otto'],['Levin','vorhanden','noch nicht abgegeben','bei Nela']]}]),
doc('20_telefonnotiz_karim.docx','Telefonnotiz Nela – Gespräch mit Karim','29.09.2026','Nela Bregenzer telefonierte am 29.09.2026 von 17:20 bis 17:43 Uhr mit Karim Vlk. Die Telefonnummer hatte sie aus einem alten Adressbuch.\n\nKarim sagte, er habe 1991 und 1992 mehrere Monate bei Berta und Hugo gewohnt, weil seine Mutter damals schwer erkrankt gewesen sei. Er könne sich an Termine bei einer Beratungsstelle erinnern. Von einer Adoption wisse er nichts. Er habe nie Bregenzer geheißen und kenne kein deutsches Adoptionsgericht.\n\nEr erinnerte sich aber an einen „Beschluss wegen Betreuung“, den seine Mutter früher aufbewahrt habe. Er wolle seine Schwester fragen, ob die Mappe noch existiere. Einen Scan habe er im Moment nicht. Nela bat ihn, keine Erklärung zu unterschreiben, bevor er seine Unterlagen gesehen habe.\n\nNela hat das Gespräch nicht aufgezeichnet. Diese Notiz wurde unmittelbar danach aus ihrer Erinnerung erstellt.'),
mail('21_levin_archivsuche.eml','Mappe ist unvollständig','2026-09-30T12:03:00+02:00','Lieber Herr Flügel,\n\nin der Kiste liegt eine Mappe „Karim 91/92“. Darin sind Schulbescheinigungen und zwei Briefe einer Beratungsstelle. Ein Gerichtsbeschluss ist nicht dabei. Auf der Mappe steht mit Bertas Schrift „Vormundschaft?“. Ich kann nicht sagen, ob das eine Frage oder ein erledigter Vorgang war.\n\nDie Briefe enthalten viele Angaben über Karims Mutter. Ich möchte sie nicht ungefragt überall verteilen. Bitte sagen Sie, welche konkrete Unterlage Sie zur Klärung brauchen. Ich kann die Mappe am Freitag ins Büro bringen.\n\nMit freundlichen Grüßen\nLevin Gottlieb Bregenzer','Levin Gottlieb Bregenzer <levin@hinterhaus.example>','Rechtsanwalt Winfried Flügel <w.fluegel@fluegel-kanzlei.example>'),
doc('22_interne_ablageansicht.png','Interne Ablageansicht – rote Mappe','30.09.2026','Mandatsablage Nela Bregenzer\nTestament 2007: beglaubigte Abschrift vorhanden\nEröffnung 14.04.2026: vorhanden\nGeburtsregister: drei Abschriften\nVollmacht 2011: Ausfertigung bei Nela\nMappe Karim: angekündigt für Freitag\nGerichtsfrist: 30.10.2026\nNoch nichts an das Grundbuchamt nachgereicht'),
doc('23_erklaerung_nela_entwurf.docx','Von Nela vorbereitete Erklärung','30.09.2026','Ich, Nela Lieselotte Bregenzer, bin ein Kind der am 08.03.2026 verstorbenen Berta Bregenzer. Meine Brüder sind Otto Samir und Levin Gottlieb Bregenzer. Nach meiner bisherigen Kenntnis hat meine Mutter keine weiteren leiblichen Kinder.\n\nZu einer möglichen Adoption von Karim Vlk kann ich derzeit keine sichere Erklärung abgeben. Er lebte Anfang der neunziger Jahre zeitweise bei meinen Eltern. Mir ist kein Adoptionsbeschluss bekannt. Am 29.09.2026 habe ich mit ihm telefoniert; er will seine Familienunterlagen prüfen.\n\nIch habe diese Erklärung selbst für das Gespräch mit dem Anwalt vorbereitet. Sie wurde weder notariell beglaubigt noch gegenüber dem Grundbuchamt als abschließender Nachweis abgegeben. Ich möchte vor einer formgerechten Erklärung wissen, welche offenen Tatsachen noch geklärt werden müssen.\n\nNela Lieselotte Bregenzer'),
mail('24_mandantenstand.eml','Bitte erst die Berichtigung, Kredit getrennt','2026-10-01T07:55:00+02:00','Sehr geehrter Herr Flügel,\n\nich habe mit meinen Brüdern gesprochen. Für die Berichtigung sind wir uns einig; das Haus soll uns in Erbengemeinschaft gehören. Über den Dachkredit entscheiden wir erst, wenn Ihre Einschätzung zur Vollmacht und die Bankbedingungen vorliegen.\n\nBitte reichen Sie noch nichts ein, bevor wir Ihre Antwort gelesen haben. Wenn Sie zuerst eine Unterlage aus Prag oder vom Gericht anfordern müssen, machen Sie dafür bitte ebenfalls den Entwurf. Ich möchte nicht, dass am Ende nur eine Liste offener Fragen übrigbleibt.\n\nMit freundlichen Grüßen\nNela Bregenzer','Nela Bregenzer <nela@hinterhaus.example>','Rechtsanwalt Winfried Flügel <w.fluegel@fluegel-kanzlei.example>')]
})
for fname,name,born,reg in [('25_geburtsregister_nela.pdf','Nela Lieselotte Bregenzer','14.07.1968','G 1482/1968'),('26_geburtsregister_otto.pdf','Otto Samir Bregenzer','06.11.1971','G 2241/1971'),('27_geburtsregister_levin.pdf','Levin Gottlieb Bregenzer','28.01.1978','G 317/1978')]:
 CASES[1]['documents'].append(doc(fname,'Geburtsregister '+name+' – Datenabschrift','28.04.2026',f'Standesamt Berlin-Nordbogen. Register {reg}. Datenabschrift der zur Mandatsakte gereichten beglaubigten Registerabschrift.\n\nAls Kind ist {name}, geboren am {born} in Berlin, eingetragen. Als Mutter ist Berta Bregenzer, geborene Tannhäusel, geboren am 22.02.1940 in Ulm, bezeichnet. Als Vater ist Hugo Bregenzer, geboren am 17.09.1938 in Berlin, bezeichnet.\n\nIn der vorgelegten Abschrift ist keine nachträgliche Änderung der Elternzuordnung vermerkt. Die Abschrift bezieht sich ausschließlich auf den bezeichneten Geburtseintrag. Sie enthält keine Aussage über weitere Kinder der Eltern.\n\nDie beglaubigte Registerabschrift liegt im Dokumentenumschlag vor. Diese Datenübertragung enthält keine Siegel, Signaturbilder oder nachgebildeten amtlichen Sicherheitsmerkmale.'))
CASES.append({
'slug':'grundbuchamt-rangtausch-am-kanal','plugin':'grundbuchamt-assistent','title':'Rangtausch am Kanal','subtitle':'Eine Werkhalle, zwei Banken und eine unvollständige Briefkette','date':'01.10.2026','client':'KanalKlang Werkstätten GmbH',
'summary':'Die KanalKlang Werkstätten GmbH baut eine ehemalige Lagerhalle in Hannover zu Proberäumen um. Für die neue Finanzierung sollen ältere Sicherheiten geordnet werden. Die Löschungsunterlagen nennen andere Banken als der Grundbuchauszug; gleichzeitig möchte der Geschäftsführer den Eigentümer des Nachbargrundstücks ermitteln.',
'assignment':'Prüfen Sie den belegten Grundbuch- und Sicherheitenstand und verfassen Sie die jetzt nötigen Nachweis- und Abstimmungsschreiben. Klären Sie, welche Rechte gelöscht, abgetreten oder im Rang geändert werden sollen und welche Einsicht für die Nachbarfrage begründbar ist. Keine Rücknahme, Einreichung oder Originalweitergabe ohne konkrete Freigabe.',
'documents':[
doc('01_auftrag_kanalklang.docx','Auftrag der KanalKlang Werkstätten GmbH','01.10.2026','Sehr geehrte Frau Rechtsanwältin Knöpfle,\n\nwir möchten die Halle am Kanal finanzieren, ohne unnötig alte Sicherheiten zu löschen und neue Gebühren auszulösen. Die neue Bank verlangt einen ersten Rang. Die alte Bank heißt inzwischen anders, und der Dienstleister Morgenrot schickt Formulare, auf denen wieder ein anderer Name steht.\n\nBitte prüfen Sie die Unterlagen und bereiten Sie die erforderlichen Schreiben vor. Der Notar soll am 12. Oktober den weiteren Vollzug besprechen. Ich möchte vorher verstehen, ob wir löschen oder abtreten und was mit dem Wegerecht passiert.\n\nAußerdem würde ich gern das Nachbargrundstück kaufen. Ich kenne den Eigentümer nicht. Unabhängig davon führt unser eingetragenes Wegerecht über dieses Grundstück, und die neue Schranke behindert die Anlieferung. Bitte trennen Sie diese beiden Fragen.\n\nMit freundlichen Grüßen\nFiete Engelbert Özdemir\nGeschäftsführer',reference='K 311/26'),
doc('02_gesellschaft_registerdaten.pdf','KanalKlang Werkstätten GmbH – Registerdatenabschrift','15.09.2026','Amtsgericht Hannover, HRB 224918. Registerdatenabschrift des zur Akte gereichten aktuellen Ausdrucks.\n\nFirma: KanalKlang Werkstätten GmbH. Sitz: Hannover. Geschäftsanschrift: Klanghafen 6, 30179 Hannover. Stammkapital: 25.000,00 EUR. Gegenstand: Vermietung und Betrieb von Proberäumen und Werkstätten sowie Herstellung akustischer Ausstattung.\n\nGeschäftsführer: Fiete Engelbert Özdemir, geboren am 10.02.1984, und Luise Noura Schlotterbeck, geboren am 19.07.1987. Die Gesellschaft wird durch zwei Geschäftsführer gemeinschaftlich vertreten. Einzelvertretungsbefugnis ist im vorgelegten Ausdruck nicht eingetragen.\n\nEine allgemeine Befreiung vom Verbot des Selbstkontrahierens ist für die beiden Geschäftsführer im Ausdruck nicht vermerkt.\n\nDie Datenabschrift bildet keine Beglaubigung oder amtliche Signatur ab. Das Original des elektronischen Abrufs befindet sich in der Notariatsakte.'),
doc('03_grundbuch_halle.pdf','Grundbuch Vahrenheide Blatt 18742 – Arbeitsabschrift','16.09.2026','Amtsgericht Hannover, Grundbuch von Vahrenheide Blatt 18742.\n\nBestandsverzeichnis: Gemarkung Vahrenheide, Flur 8, Flurstück 94/11, Gebäude- und Freifläche Klanghafen 6, 1.460 m².\n\nAbteilung 1: KanalKlang Werkstätten GmbH, Hannover, eingetragen am 09.03.2018.\n\nAbteilung 2: Nummer 1, beschränkte persönliche Dienstbarkeit für die Leitungsbogen Netz GmbH zur Führung einer Fernwärmeleitung. Eintragung am 12.06.1995; Bewilligung vom 19.05.1995.\n\nAbteilung 3: Nummer 1, 180.000,00 EUR Briefgrundschuld für die Nordbogen Kreditbank AG, 15 Prozent Zinsen, 5 Prozent Nebenleistung, eingetragen am 09.03.2018. Nummer 2, 60.000,00 EUR Buchgrundschuld für die Tonspur Förderbank GmbH, 10 Prozent Zinsen, 5 Prozent Nebenleistung. Der Vorrang für künftig zu bestellende Grundpfandrechte bis insgesamt 400.000,00 EUR mit bis zu 18 Prozent Zinsen und 10 Prozent Nebenleistung ist vorbehalten. Eingetragen am 22.11.2021.\n\nZum Rangvorbehalt und zur Dienstbarkeit sind die Bezugsurkunden erforderlich. Diese Abschrift enthält keine Aussage über den gegenwärtigen Darlehenssaldo.'),
doc('04_grundbuch_nachbar_bezug.txt','Auszug aus der Erwerbsakte zum Nachbargrundstück','20.09.2026','In der Erwerbsakte von 2018 liegt eine Notiz des damaligen Notars: Das Grundstück Blatt 18742 ist durch ein Geh- und Fahrrecht über Flurstück 94/10 begünstigt. Das belastete Grundstück wird im Grundbuch Vahrenheide Blatt 17580 geführt. Als Bewilligung wird die Urkunde vom 19.05.1995 genannt.\n\nDer damalige Käuferauszug aus Blatt 17580 liegt in der übersandten Mappe nicht. Der Plan ist nur als schlecht lesbare Faxkopie vorhanden. Auf der Kopie ist ein 3 Meter breiter Streifen entlang der östlichen Grenze erkennbar.\n\nFiete notiert: „Seit August steht dort eine Schranke. Unser Lieferwagen passt nur durch, wenn jemand aufsperrt. Wer ist heute Eigentümer? Für Kaufgespräch wäre das auch gut.“\n\nÜbertragen aus der Papierakte durch Luise Schlotterbeck.'),
doc('05_darlehenssaldo_alt.xlsx','Darlehen und Sicherheiten – Arbeitsübersicht','25.09.2026','',sheets=[{'name':'Darlehen','headers':['Darlehen','Ursprünglich EUR','Rest laut Schreiben EUR','Stichtag','Ansprechpartner'],'rows':[['NB-2018-441',160000,38450.75,'30.09.2026','Morgenrot Service'],['TF-2021-883',50000,27900,'30.09.2026','Tonspur Förderbank'],['Gesamt', '=SUM(B2:B3)','=SUM(C2:C3)','30.09.2026','Arbeitswert ohne Tageszinsen']], 'formats':{'B':'0.00','C':'0.00'}},{'name':'Rechte','headers':['Recht','Nominal EUR','Brief','Eingetragener Gläubiger','Offene Unterlage'],'rows':[['Abt. 3 Nr. 1',180000,'ja','Nordbogen Kreditbank AG','vollständige Abtretungskette'],['Abt. 3 Nr. 2',60000,'nein','Tonspur Förderbank GmbH','Rangzustimmung'],['Gewünschte neue Sicherheit',310000,'noch offen','Hafenlicht Bank eG','genaue Verwendung Altgrundschuld']]}]),
doc('06_nordbogen_verschmelzung.pdf','Registervermerk Bankverschmelzung – Datenabschrift','08.07.2022','Amtsgericht Hannover, HRB 207441, Nordbogen Kreditbank AG. Arbeitsabschrift des zur Akte gereichten Registervermerks.\n\nDie Gesellschaft ist aufgrund des Verschmelzungsvertrags vom 20.05.2022 und der Zustimmungsbeschlüsse mit der Hanseatische Bogenbank AG mit Sitz in Hamburg, Amtsgericht Hamburg HRB 118872, als übernehmendem Rechtsträger verschmolzen. Die Verschmelzung wurde am 08.07.2022 im Register des übernehmenden Rechtsträgers eingetragen.\n\nDie Firma Nordbogen Kreditbank AG ist erloschen.\n\nDie Abschrift enthält nur den bezeichneten Registervorgang. Eine spätere Abtretung einzelner Grundpfandrechte wird durch diesen Auszug nicht dokumentiert. Der vollständige Abruf mit Herkunftsdatei liegt beim Notariat.'),
doc('07_abtretung_2023_auszug.pdf','Abtretung an Hafenboden Sicherheiten GmbH – Arbeitskopie','14.03.2023','Hanseatische Bogenbank AG und Hafenboden Sicherheiten GmbH haben eine Abtretung bestimmter Grundpfandrechte vereinbart. Der zur Akte gereichte Auszug benennt unter Position 47 die Grundschuld in Hannover-Vahrenheide Blatt 18742, Abteilung 3 laufende Nummer 1, über 180.000,00 EUR.\n\nDer Auszug enthält den Text, dass die bezeichnete Grundschuld nebst Zinsen und Nebenleistungen an die Hafenboden Sicherheiten GmbH abgetreten wird. Die Abtretung soll mit der vereinbarten Übergabe der zugehörigen Briefurkunde vollzogen werden.\n\nDie vorliegende Kopie umfasst die Seiten 1, 2 und 8 der Vertragsmappe. Die Unterschrifts- und Beglaubigungsseiten sowie die Übergabeliste sind in der von Morgenrot übersandten Datei nicht enthalten.\n\nFiete hat am Rand notiert: „Bitte vollständige Fassung besorgen. Nicht klar, ob Brief wirklich mitging.“'),
mail('08_morgenrot_service.eml','Ablösung und Unterlagen Halle Klanghafen','2026-09-18T11:14:00+02:00','Sehr geehrter Herr Özdemir,\n\nwir bearbeiten den Vorgang als Dienstleister der Hafenboden Sicherheiten GmbH. Die vorläufige Ablösesumme zum 30.09.2026 beträgt 38.450,75 EUR. Tageszinsen und mögliche Kosten bis zum tatsächlichen Zahlungstag werden gesondert berechnet. Bitte überweisen Sie noch nicht auf Grundlage dieser Vorabinformation.\n\nAnbei erhalten Sie einen Auszug aus der Abtretungsmappe sowie die von unserem Auftraggeber vorbereitete Löschungsbewilligung. Den Originalbrief müssen wir über unser externes Verwahrzentrum anfordern. Nach unserer Liste wird er unter Nummer 02/918773 geführt.\n\nMit freundlichen Grüßen\nKunigunde Bell\nMorgenrot Service GmbH','Kunigunde Bell <k.bell@morgenrot-service.example>','Fiete Özdemir <fiete@kanalklang.example>'),
doc('09_loeschungsbewilligung_entwurf.docx','Von Hafenboden übersandter Entwurf','17.09.2026','Die Hafenboden Sicherheiten GmbH bewilligt die Löschung der im Grundbuch von Vahrenheide Blatt 18742, Abteilung 3 laufende Nummer 1, eingetragenen Grundschuld von 180.000,00 EUR mit Zinsen und Nebenleistungen.\n\nDie Erklärung soll nach Eingang des endgültig abgerechneten Ablösebetrags zur Verfügung gestellt werden. Für die Gesellschaft ist Kunigunde Bell als Bevollmächtigte vorgesehen. Eine Vollmachtsurkunde liegt dieser Entwurfsdatei nicht bei.\n\nDer Entwurf trägt auf der letzten Seite den Vermerk „Beglaubigung nach Freigabe“. Er enthält keine Unterschrift und keinen Beglaubigungsvermerk.\n\nAn die KanalKlang Werkstätten GmbH übermittelt zur Abstimmung der genauen Grundstücksbezeichnung. Eine Abtretung an die neue finanzierende Bank ist in diesem Text nicht geregelt.'),
mail('10_neue_bank_anforderung.eml','Finanzierung: Vorrang und alte Grundschuld','2026-09-19T09:42:00+02:00','Sehr geehrte Frau Schlotterbeck, sehr geehrter Herr Özdemir,\n\nfür das Darlehen von 286.000,00 EUR benötigen wir eine Sicherheit von 310.000,00 EUR im vertraglich vereinbarten Rang. Wir können prüfen, ob die bestehende Grundschuld von 180.000,00 EUR an uns abgetreten und durch eine weitere Sicherheit ergänzt wird. Eine Löschung der alten Grundschuld ist nicht unsere pauschale Vorgabe.\n\nDie Dienstbarkeit für die Fernwärmeleitung und die Grundschuld der Tonspur Förderbank müssen wir anhand der Urkunden prüfen. Bitte reichen Sie den vollständigen Rangvorbehalt ein. Der vereinfachte Hinweis „erster Rang“ in unserer ersten Checkliste war noch keine abschließende Aussage zu den bestehenden Rechten.\n\nMit freundlichen Grüßen\nRomy Walburga Aydin\nHafenlicht Bank eG','Romy Aydin <romy.aydin@hafenlicht-bank.example>','Luise Schlotterbeck <luise@kanalklang.example>'),
doc('11_bank_checkliste_alt.docx','Erste Unterlagenliste Hafenlicht Bank','02.09.2026','KanalKlang Werkstätten GmbH – Finanzierung Ausbau Werkhalle. Vorläufige Unterlagenliste des Kundenbetreuers.\n\nBenötigt werden ein aktueller Grundbuchauszug, ein vollständiger Handelsregisterauszug, Jahresabschluss 2025, Kostenaufstellung, Eigenmittelnachweis und Angebote. Als Sicherung ist eine Grundschuld von 310.000,00 EUR im ersten Rang vorgesehen.\n\nBestehende Rechte werden nach Vorlage der Unterlagen einzeln bewertet. Diese Liste enthält keine Zusage einer bestimmten Abwicklung der Altgrundschuld. Die rechtliche und wirtschaftliche Kreditentscheidung bleibt vorbehalten.\n\nFiete hat auf seinem Ausdruck mit Kugelschreiber ergänzt: „Altbank löschen, neue rein?“ Die handschriftliche Ergänzung stammt nicht von der Bank.\n\nKontaktperson: Romy Walburga Aydin.'),
doc('12_tonspur_rangbrief.docx','Tonspur Förderbank: Anfrage zur Rangänderung','23.09.2026','Sehr geehrte Damen und Herren,\n\nSie haben um Zustimmung zum Vorrang einer neuen Grundschuld der Hafenlicht Bank eG gebeten. Für die Prüfung benötigen wir den genauen Betrag, die Zinsen und Nebenleistungen sowie einen vollständigen Entwurf der beabsichtigten Rangregelung.\n\nUnsere Grundschuld von 60.000,00 EUR soll nicht ohne ausdrückliche Zustimmung in einem weitergehenden Umfang zurücktreten. Bitte erläutern Sie insbesondere, ob die bestehende Grundschuld über 180.000,00 EUR erhalten bleibt, abgetreten oder gelöscht wird. Aus Ihrer Mail vom 20.09.2026 ist dies nicht eindeutig erkennbar.\n\nEine Zustimmung wird mit dieser Nachricht nicht erteilt. Wir rechnen nach Eingang vollständiger Unterlagen mit zehn Arbeitstagen für die Prüfung.\n\nMit freundlichen Grüßen\nBruno Zipfel\nTonspur Förderbank GmbH'),
doc('13_rangvorbehalt_urkunde.pdf','Rangvorbehalt bei der Fördergrundschuld – Textauszug','08.11.2021','Notarin Roswitha Kanters, Urkundenrolle 512/2021. Textauszug zur Rangbestimmung.\n\nBei der Bestellung der Grundschuld zugunsten der Tonspur Förderbank GmbH wird zugunsten des Eigentümers der Vorrang für künftig zu bestellende Grundpfandrechte bis zu einem Gesamtkapitalbetrag von 400.000,00 EUR nebst bis zu 18 Prozent jährlichen Zinsen und einmaliger Nebenleistung bis zu 10 Prozent vorbehalten. Der Vorbehalt betrifft den Rang vor der hier bestellten Fördergrundschuld.\n\nDie bereits bestehende Dienstbarkeit zugunsten der Leitungsbogen Netz GmbH wird durch diese Vereinbarung nicht ohne deren Mitwirkung in ihrem Rang verändert. Weitere Vereinbarungen zur Ausnutzung des Vorbehalts sind in den übrigen Teilen dieser Bestellungsurkunde geregelt.\n\nDie zu dieser Arbeitskopie übersandte Anlage enthält die Rangbestimmung auf Seite 16. Die Seiten 17 bis 19 mit weiteren Vollzugsbestimmungen hat die Gesellschaft noch nicht aus ihrem Archiv eingescannt.'),
doc('14_dienstbarkeit_waerme.pdf','Fernwärmeleitung – Textabschrift der Bewilligung','19.05.1995','Der Eigentümer bewilligt zugunsten der Leitungsbogen Netz GmbH eine beschränkte persönliche Dienstbarkeit zur Errichtung, Unterhaltung, Erneuerung und Kontrolle einer Fernwärmeleitung auf dem im beigefügten Lageplan bezeichneten Streifen des Grundstücks.\n\nDer Streifen ist von dauerhaften Überbauungen freizuhalten. Die Berechtigte darf ihn nach angemessener Ankündigung betreten und mit geeigneten Fahrzeugen befahren; bei Gefahr im Verzug bedarf es keiner vorherigen Ankündigung. Nach Arbeiten ist der vorherige Zustand im erforderlichen Umfang wiederherzustellen.\n\nEine Veränderung des Rangs ist in dieser Bewilligung nicht erklärt. Der Lageplan zeigt einen Streifen entlang der südlichen Grundstücksgrenze. Der aktuelle Umbauplan sieht in diesem Bereich zwei Fahrradboxen vor.\n\nTextabschrift aus der Erwerbsakte. Die Plananlage liegt als gesondertes Dokument vor.'),
doc('15_plan_abgleich.txt','Planbesprechung mit der Architektin','24.09.2026','Besprechung 24.09.2026, 14:00 Uhr. Teilnehmer: Luise Schlotterbeck, Fiete Özdemir und Architektin Sanja Ottilie Klee.\n\nDie Architektin weist darauf hin, dass die geplanten Fahrradboxen auf dem Streifen der Fernwärmeleitung liegen könnten. Der Plan von 1995 ist nicht maßstäblich genug, um die heutige Zaunlinie sicher zuzuordnen. Eine aktuelle Leitungsplanauskunft ist angefordert.\n\nLuise möchte die Boxen notfalls an die Nordseite setzen. Fiete fragt, ob das die Bankfinanzierung verzögert. Frau Klee sagt, sie könne nur die Planung, nicht die Rang- und Sicherheitenfragen beantworten.\n\nFür die nächste Besprechung soll ein aktueller Plan mit Flurstücksgrenzen vorliegen. Eine Zustimmung des Netzbetreibers liegt bislang nicht vor.'),
mail('16_brieflager_antwort.eml','Verwahrzentrum: Zuordnung der Briefnummer','2026-09-25T15:29:00+02:00','Sehr geehrte Frau Bell,\n\nzu Ihrer Anfrage haben wir im System einen Brief mit Nummer 02/918773 gefunden. Der zugehörige Umschlag ist mit „Vahrenheide 18742, 180 T“ beschriftet. In der elektronischen Übergabeliste vom März 2023 steht jedoch bei dieser Position die Nummer 02/918737. Wir können derzeit nicht ausschließen, dass zwei Ziffern vertauscht wurden.\n\nVor einem Versand benötigen wir die Freigabe zur Einsicht des Originals im Vieraugenverfahren und einen Abgleich mit der Übernahmeliste. Der Umschlag bleibt bis dahin im Bestand. Wir versenden keine Urkunde allein anhand einer telefonischen Bitte.\n\nMit freundlichen Grüßen\nAdelheid Pusteblum\nSicherheitenlager Nord GmbH','Adelheid Pusteblum <a.pusteblum@sicherheitenlager.example>','Kunigunde Bell <k.bell@morgenrot-service.example>'),
doc('17_notariat_nachforderung.docx','Unterlagenanforderung des Notariats','28.09.2026','Sehr geehrte Frau Schlotterbeck, sehr geehrter Herr Özdemir,\n\nfür den vorgesehenen Besprechungstermin benötigen wir die vollständige Bestellungsurkunde von 2021 einschließlich der Seiten 17 bis 19, die aktuelle schriftliche Ranganforderung der Hafenlicht Bank und die Unterlagen zur Gläubigerkette der Briefgrundschuld. Bitte reichen Sie die Erklärung der Tonspur Förderbank nach, sobald eine konkrete Rangregelung abgestimmt ist.\n\nDie Entwurfsdatei der Löschungsbewilligung enthält weder die angekündigte Beglaubigung noch einen Nachweis der Vollmacht der vorgesehenen Unterzeichnerin. Ob gelöscht oder abgetreten werden soll, muss vor der Endfassung feststehen.\n\nBitte beachten Sie außerdem die gemeinschaftliche Vertretung Ihrer Gesellschaft. Ein allein von Herrn Özdemir unterschriebenes Abstimmungsblatt ist nicht ohne Weiteres eine abschließende Erklärung der GmbH.\n\nMit freundlichen Grüßen\nNotarin Roswitha Kanters'),
doc('18_nachbar_schranke_protokoll.docx','Anlieferung und Schranke','26.09.2026','Protokoll der KanalKlang Werkstätten GmbH.\n\nAm 26.09.2026 um 07:35 Uhr traf ein Lieferfahrzeug mit Akustikplatten ein. Die Schranke auf dem Weg über Flurstück 94/10 war geschlossen. Ein Schild nannte die Telefonnummer einer Hausverwaltung, ohne den Eigentümer zu bezeichnen. Nach zwei Anrufen kam um 08:12 Uhr ein Hausmeister und öffnete.\n\nDer Fahrer sagte, sein Fahrzeug sei 2,35 Meter breit. Fiete schätzte die verbleibende Durchfahrt bei halb geöffneter Schranke auf weniger als drei Meter, hat jedoch nicht gemessen. Auf dem Nachbargrundstück standen keine Verkaufsschilder.\n\nLuise fotografierte die Schranke und das Schild für die interne Dokumentation. Eine Veröffentlichung ist nicht vorgesehen. Sie möchte die Reichweite des bestehenden Geh- und Fahrrechts klären. Fiete möchte zusätzlich wissen, ob der Eigentümer verkaufen würde.\n\nAufgenommen von Luise Noura Schlotterbeck.'),
mail('19_einsichtsanfrage_alt.eml','Eigentümer Nachbargrundstück gesucht','2026-09-27T10:08:00+02:00','Sehr geehrte Damen und Herren,\n\nwir betreiben die Halle Klanghafen 6 und möchten das Grundstück nebenan möglicherweise kaufen. Können Sie uns sagen, wer Eigentümer ist und wie wir ihn erreichen? Es handelt sich nach unserer alten Akte um Vahrenheide Blatt 17580.\n\nWir würden bei passendem Preis kurzfristig verhandeln. Einen Kontakt zum Eigentümer haben wir noch nicht.\n\nMit freundlichen Grüßen\nFiete Özdemir','Fiete Özdemir <fiete@kanalklang.example>','Grundbuchservice <grundbuch@amtsgericht-kanalbogen.example>'),
doc('20_antwort_einsicht.docx','Antwort zur Eigentümeranfrage – Textabschrift','29.09.2026','Sehr geehrter Herr Özdemir,\n\nIhre Anfrage vom 27.09.2026 ist eingegangen. Allein der Wunsch, den Eigentümer für erstmalige Kaufverhandlungen zu ermitteln, legt kein berechtigtes Interesse an der begehrten Auskunft dar. Die Mitteilung der Eigentümerkontaktdaten kann auf dieser Grundlage nicht erfolgen.\n\nSollten Sie eine konkrete eigene Rechtsposition geltend machen, die sich auf das bezeichnete Grundstück bezieht, ist diese mit dem benötigten Umfang der Einsicht und geeigneten Nachweisen darzustellen. Eine allgemeine Kaufabsicht ersetzt dies nicht.\n\nMit freundlichen Grüßen\nUrkundsbeamtin der Geschäftsstelle\nTextabschrift des eingegangenen Schreibens'),
doc('21_geschaeftsfuehrerchat.txt','Chat „Finanzierung ohne Knoten“','30.09.2026','08:31 Fiete: Ich dachte, wir schicken den Brief einfach zur neuen Bank und fertig.\n08:34 Luise: Die Nummern stimmen nicht. Außerdem sagt die neue Bank, Abtretung prüfen, nicht löschen.\n08:36 Fiete: Dann bitte nichts löschen. Und die Nachbarn: Das Gericht hat wegen Kauf abgelehnt.\n08:40 Luise: Wir brauchen die Wegerechtsurkunde wegen der Schranke. Das ist unser echter Punkt, kein Trick fürs Kaufgespräch.\n08:42 Fiete: Einverstanden. Ich frage trotzdem separat die Hausverwaltung, ob sie einen Kaufbrief weiterleitet.\n08:44 Luise: Lass Knöpfle erst die Schreiben machen. Ich will alles sehen, bevor eine Bewilligung rausgeht.\n\nExport durch Luise am 30.09.2026.'),
doc('22_rangvarianten_arbeitsblatt.xlsx','Rangvarianten und offene Erklärungen','30.09.2026','',sheets=[{'name':'Varianten','headers':['Variante','Altgrundschuld EUR','Zusatzgrundschuld EUR','Summe nominal EUR','Bankbestätigung'],'rows':[['Abtretung und Ergänzung',180000,130000,'=B2+C2','offen'],['Löschung und Neubestellung',0,310000,'=B3+C3','nicht gewählt'],['Nur vorhandene Sicherheit',180000,0,'=B4+C4','laut Finanzierungshöhe nicht ausreichend']], 'formats':{'B':'0.00','C':'0.00','D':'0.00'}},{'name':'Erklaerungen','headers':['Stelle','Erforderliche Klärung','Stand','Termin'],'rows':[['Hafenboden','Gläubigerkette und Vertretung','angefordert','05.10.2026'],['Verwahrzentrum','Originalnummer und Übergabe','Prüfung offen','05.10.2026'],['Tonspur','konkreter Rangumfang','keine Zustimmung','nach Entwurf'],['Hafenlicht','akzeptierter Endrang','Unterlagen fehlen','vor Notartermin'],['Leitungsbogen','Leitungsverlauf','Plan angefordert','offen']]}]),
doc('23_interner_status.png','Interne Vollzugsübersicht KanalKlang','01.10.2026','KanalKlang – interner Arbeitsstand\nNotariatstermin 12.10.2026\nKeine Löschung beauftragt\nKeine Abtretung unterschrieben\nOriginalbrief noch im Verwahrzentrum\nAbweichende Nummer: 918773 / 918737\nGrundbuchfrist: bisher keine Zwischenverfügung\nNachbar: Einsichtsanfrage wegen Kauf abgelehnt\nWegerechtsurkunde wird benötigt'),
mail('24_abschlussauftrag_luise.eml','Was bis zum Notartermin vorliegen soll','2026-10-01T09:05:00+02:00','Sehr geehrte Frau Knöpfle,\n\nbitte erstellen Sie für uns die Schreiben an Morgenrot beziehungsweise die Hafenboden, an die neue Bank und an die Tonspur Förderbank. Für die Nachbarfrage benötigen wir einen Antrag, der sich auf die wirkliche Wegerechtsfrage bezieht. Bitte keine erfundenen Kaufverhandlungen und keine allgemeine Datenabfrage.\n\nWir möchten außerdem eine kurze verständliche Rangübersicht. Fiete und ich entscheiden dann gemeinsam über den gewählten Weg. Wenn eine Erklärung zum Notar muss, kennzeichnen Sie bitte genau welche. Nicht jede Mail soll mit „nur der Notar darf das“ enden.\n\nWir geben vorerst nur die Vorbereitung frei. Die Unterlagen werden nach gemeinsamer Durchsicht versandt.\n\nMit freundlichen Grüßen\nLuise Noura Schlotterbeck','Luise Schlotterbeck <luise@kanalklang.example>','Rechtsanwältin Minna Knöpfle <m.knoepfle@knoepfle-kanzlei.example>')]
})

